settings.custom_liquid:
{%- comment -%}
  Bandeau de preuve sociale. Placeholder neutre : Romeo remplace texte et visuels a sa main.
{%- endcomment -%}
<div class="zmon zmon-sp">
  <div class="zmon-sp__avatars">
    {%- for im in product.images limit: 3 -%}
      <img class="zmon-sp__av" src="{{ im | image_url: width: 60 }}" alt="" loading="lazy" width="18" height="18">
    {%- endfor -%}
  </div>
  <span class="zmon-sp__txt"><strong>Adoptée par plus de 500 000 femmes</strong></span>
</div>
<style>
.zmon-sp{
  --zmon-ink: rgb(var(--color-base-text));
  --zmon-accent: rgb(var(--color-base-accent-1));
  --zmon-accent-2: rgb(var(--color-base-accent-2));
  --zmon-on-accent: rgb(var(--color-base-solid-button-labels));
  --zmon-soft: rgb(var(--color-base-accent-1) / 0.10);
  --zmon-line: rgb(var(--color-base-accent-1) / 0.22);
  --zmon-muted: rgb(var(--color-base-text) / 0.62);
  /* couleurs SEMANTIQUES (alerte / disponibilite), hors palette de marque */
  --zmon-warn: #E68A00;
  --zmon-ok: #00B67A;
display:flex;align-items:center;gap:6px;line-height:1.2;font-size:12px;color:var(--zmon-ink)}
.zmon-sp__avatars{display:flex;flex-shrink:0}
.zmon-sp__av{width:18px;height:18px;border-radius:50%;object-fit:cover;border:.5px solid #fff;margin-left:-8px}
.zmon-sp__av:first-child{margin-left:0}
.zmon-sp__txt{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
</style>

{%- assign v = product.selected_or_first_available_variant -%}
<div class="zmon zmon-price">
  {%- if v.compare_at_price > v.price -%}<span class="zmon-price__old">{{ v.compare_at_price | money }}</span>{%- endif -%}
  <span class="zmon-price__now">{{ v.price | money }}</span>
  {%- if v.compare_at_price > v.price -%}
    {%- assign ecart = v.compare_at_price | minus: v.price | times: 1000 | divided_by: v.compare_at_price -%}
    {%- assign pct = ecart | plus: 5 | divided_by: 10 -%}
    <span class="zmon-price__badge">-{{ pct }}% + LIVRAISON OFFERTE</span>
  {%- endif -%}
</div>
<style>
.zmon-price{
  --zmon-ink: rgb(var(--color-base-text));
  --zmon-accent: rgb(var(--color-base-accent-1));
  --zmon-accent-2: rgb(var(--color-base-accent-2));
  --zmon-on-accent: rgb(var(--color-base-solid-button-labels));
  --zmon-soft: rgb(var(--color-base-accent-1) / 0.10);
  --zmon-line: rgb(var(--color-base-accent-1) / 0.22);
  --zmon-muted: rgb(var(--color-base-text) / 0.62);
  /* couleurs SEMANTIQUES (alerte / disponibilite), hors palette de marque */
  --zmon-warn: #E68A00;
  --zmon-ok: #00B67A;
display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.zmon-price__old,.zmon-price__now{font-variant-numeric:lining-nums tabular-nums;letter-spacing:-.2px;font-size:18px}
.zmon-price__old{color:var(--zmon-ink);opacity:.75;text-decoration:line-through;font-weight:400}
.zmon-price__now{color:var(--zmon-accent);font-weight:600}
.zmon-price__badge{background:var(--zmon-accent);color:var(--zmon-on-accent);font-size:8px;font-weight:600;
  padding:5px 8px;border-radius:6px;white-space:nowrap;line-height:1}
</style>

{%- assign jours = 'Dim,Lun,Mar,Mer,Jeu,Ven,Sam' | split: ',' -%}
{%- assign mois = 'janv.,févr.,mars,avr.,mai,juin,juil.,août,sept.,oct.,nov.,déc.' | split: ',' -%}
{%- comment -%} Date calculée en Liquid : le JS ne s'exécute pas dans un Custom Liquid Shrine. {%- endcomment -%}
{%- assign t = 'now' | date: '%s' | times: 1 -%}
{%- assign heure = 'now' | date: '%H' | times: 1 -%}
{%- if heure >= 14 -%}{%- assign t = t | plus: 86400 -%}{%- endif -%}
{%- assign js = t | date: '%w' | times: 1 -%}
{%- if js == 6 -%}{%- assign t = t | plus: 172800 -%}{%- elsif js == 0 -%}{%- assign t = t | plus: 86400 -%}{%- endif -%}
{%- assign js2 = t | date: '%w' | times: 1 -%}
{%- assign mi = t | date: '%-m' | times: 1 | minus: 1 -%}
<div class="zmon zmon-ship">
  <span class="zmon-ship__dot"></span>
  {%- assign jnum = t | date: '%-d' | times: 1 -%}
  {%- if jnum == 1 -%}{%- assign jlbl = '1er' -%}{%- else -%}{%- assign jlbl = jnum -%}{%- endif -%}
  <span class="zmon-ship__txt">Expédition le <strong>{{ jours[js2] }} {{ jlbl }} {{ mois[mi] }}</strong></span>
  <span class="zmon-ship__free">&#127467;&#127479; Livraison <strong>FR</strong> offerte</span>
</div>
<style>
.zmon-ship{
  --zmon-ink: rgb(var(--color-base-text));
  --zmon-accent: rgb(var(--color-base-accent-1));
  --zmon-accent-2: rgb(var(--color-base-accent-2));
  --zmon-on-accent: rgb(var(--color-base-solid-button-labels));
  --zmon-soft: rgb(var(--color-base-accent-1) / 0.10);
  --zmon-line: rgb(var(--color-base-accent-1) / 0.22);
  --zmon-muted: rgb(var(--color-base-text) / 0.62);
  /* couleurs SEMANTIQUES (alerte / disponibilite), hors palette de marque */
  --zmon-warn: #E68A00;
  --zmon-ok: #00B67A;
display:flex;align-items:center;justify-content:space-between;width:100%;gap:10px;
  padding:10px 12px;border:.7px solid var(--zmon-ink);border-radius:8px;box-sizing:border-box;margin-top:4px}
.zmon-ship__dot{position:relative;width:8px;height:8px;background:var(--zmon-ok);border-radius:50%;flex-shrink:0}
.zmon-ship__dot::after{content:"";position:absolute;inset:0;background:var(--zmon-ok);border-radius:50%;animation:zmonPulse 1.6s infinite;opacity:.6}
.zmon-ship__txt{font-size:12px;color:var(--zmon-ink);flex:1}
.zmon-ship__txt strong{font-weight:700}
.zmon-ship__free{font-size:12px;font-weight:500;white-space:nowrap;color:var(--zmon-ink)}
</style>

{%- assign jours = 'Dim,Lun,Mar,Mer,Jeu,Ven,Sam' | split: ',' -%}
{%- assign mois = 'janv.,févr.,mars,avr.,mai,juin,juil.,août,sept.,oct.,nov.,déc.' | split: ',' -%}
{%- assign fin = 'now' | date: '%s' | times: 1 | plus: 172800 -%}
{%- assign fmi = fin | date: '%-m' | times: 1 | minus: 1 -%}
{%- assign nb = cart.item_count -%}
{%- if nb > 2 -%}{%- assign nb = 2 -%}{%- endif -%}
{%- assign pct = nb | times: 50 -%}
<div class="zmon zmon-bogo">
  <p class="zmon-bogo__t"><strong>LIQUIDATION &middot; 2 montres pour le prix d'1</strong>
    {%- assign fjn = fin | date: '%-d' | times: 1 -%}
    {%- if fjn == 1 -%}{%- assign fjl = '1er' -%}{%- else -%}{%- assign fjl = fjn -%}{%- endif -%}
    <span class="zmon-bogo__d">se termine le {{ fjl }} {{ mois[fmi] }}</span></p>
  <p class="zmon-bogo__s">Ajoute tes montres préférées au panier. La promotion s'applique automatiquement.</p>
  <div class="zmon-bogo__bar"><div class="zmon-bogo__fill" style="width:{{ pct }}%"></div></div>
  <p class="zmon-bogo__f">Sélectionne <strong>2</strong> montres pour activer la promotion.</p>
</div>
<style>
.zmon-bogo{
  --zmon-ink: rgb(var(--color-base-text));
  --zmon-accent: rgb(var(--color-base-accent-1));
  --zmon-accent-2: rgb(var(--color-base-accent-2));
  --zmon-on-accent: rgb(var(--color-base-solid-button-labels));
  --zmon-soft: rgb(var(--color-base-accent-1) / 0.10);
  --zmon-line: rgb(var(--color-base-accent-1) / 0.22);
  --zmon-muted: rgb(var(--color-base-text) / 0.62);
  /* couleurs SEMANTIQUES (alerte / disponibilite), hors palette de marque */
  --zmon-warn: #E68A00;
  --zmon-ok: #00B67A;
background:var(--zmon-soft);border:1px solid var(--zmon-line);border-radius:16px;
  padding:1.25rem;margin-top:1.4rem;color:var(--zmon-ink)}
.zmon-bogo__t{margin:0 0 .5rem;font-size:1.05rem;line-height:1.4}
.zmon-bogo__d{font-weight:400;margin-left:.25rem}
.zmon-bogo__s{margin:0 0 1rem;font-size:.92rem;line-height:1.5;opacity:.8}
.zmon-bogo__bar{background:rgb(var(--color-base-text) / 0.08);height:.6rem;border-radius:999px;overflow:hidden;margin-bottom:1rem}
.zmon-bogo__fill{height:100%;background:var(--zmon-accent);border-radius:999px;transition:width .3s}
.zmon-bogo__f{margin:0;font-size:.95rem;line-height:1.5}
.zmon-bogo strong{font-weight:700}
</style>

{%- comment -%} Carrousel : swipe CSS pur, aucun JS (non executé dans un Custom Liquid Shrine). {%- endcomment -%}
<div class="zmon zmon-vc">
  <div class="zmon-vc__track">
    {%- assign nv = 0 -%}
    {%- for m in product.media -%}{%- if m.media_type == 'video' -%}{%- assign nv = nv | plus: 1 -%}
      <div class="zmon-vc__item">{{ m | video_tag: controls: true, muted: true, playsinline: true, preload: 'metadata' }}</div>
    {%- endif -%}{%- endfor -%}
    {%- if nv == 0 -%}{%- for im in product.images limit: 4 -%}
      <div class="zmon-vc__item"><img src="{{ im | image_url: width: 400 }}" alt="" loading="lazy"></div>
    {%- endfor -%}{%- endif -%}
  </div>
</div>
<style>
.zmon-vc{
  --zmon-ink: rgb(var(--color-base-text));
  --zmon-accent: rgb(var(--color-base-accent-1));
  --zmon-accent-2: rgb(var(--color-base-accent-2));
  --zmon-on-accent: rgb(var(--color-base-solid-button-labels));
  --zmon-soft: rgb(var(--color-base-accent-1) / 0.10);
  --zmon-line: rgb(var(--color-base-accent-1) / 0.22);
  --zmon-muted: rgb(var(--color-base-text) / 0.62);
  /* couleurs SEMANTIQUES (alerte / disponibilite), hors palette de marque */
  --zmon-warn: #E68A00;
  --zmon-ok: #00B67A;
margin:25px 0 20px}
.zmon-vc__track{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;gap:14px;padding:10px 0;
  scrollbar-width:none;-webkit-overflow-scrolling:touch}
.zmon-vc__track::-webkit-scrollbar{display:none}
.zmon-vc__item{flex:0 0 auto;scroll-snap-align:start;border-radius:16px;overflow:hidden;width:140px;height:250px;
  background:var(--zmon-soft);position:relative}
.zmon-vc__item video,.zmon-vc__item img{width:100%;height:100%;object-fit:cover;border-radius:16px;display:block}
@media(min-width:601px){.zmon-vc__item{width:180px;height:320px}}
</style>

{%- assign p = all_products['emeraude-doree'] -%}
<div class="zmon zmon-so">
  <h2 class="zmon-so__t">Rejoins #zooryn</h2>
