      {%- if im -%}<img src="{{ im | image_url: width: 600 }}" alt="" loading="lazy">{%- endif -%}
      <div class="zmon-so__tag"><span class="zmon-so__ig"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M7 2C4.2 2 2 4.2 2 7v10c0 2.8 2.2 5 5 5h10c2.8 0 5-2.2 5-5V7c0-2.8-2.2-5-5-5H7zm0 2h10c1.7 0 3 1.3 3 3v10c0 1.7-1.3 3-3 3H7c-1.7 0-3-1.3-3-3V7c0-1.7 1.3-3 3-3zm11 1a1 1 0 1 0 0 2 1 1 0 0 0 0-2zM12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10zm0 2a3 3 0 1 1 0 6 3 3 0 0 1 0-6z"/></svg></span>@sophie.letjens</div>
    </div>
    <div class="zmon-so__c">
      {%- assign im = p.images[1] -%}
