      <div class="zmon-so__tag"><span class="zmon-so__ig"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M7 2C4.2 2 2 4.2 2 7v10c0 2.8 2.2 5 5 5h10c2.8 0 5-2.2 5-5V7c0-2.8-2.2-5-5-5H7zm0 2h10c1.7 0 3 1.3 3 3v10c0 1.7-1.3 3-3 3H7c-1.7 0-3-1.3-3-3V7c0-1.7 1.3-3 3-3zm11 1a1 1 0 1 0 0 2 1 1 0 0 0 0-2zM12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10zm0 2a3 3 0 1 1 0 6 3 3 0 0 1 0-6z"/></svg></span>@emma.richardson</div>
    </div>
    <div class="zmon-so__c">
      {%- assign im = p.images[2] -%}
      {%- if im -%}<img src="{{ im | image_url: width: 600 }}" alt="" loading="lazy">{%- endif -%}
      <div class="zmon-so__tag"><span class="zmon-so__ig"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M7 2C4.2 2 2 4.2 2 7v10c0 2.8 2.2 5 5 5h10c2.8 0 5-2.2 5-5V7c0-2.8-2.2-5-5-5H7zm0 2h10c1.7 0 3 1.3 3 3v10c0 1.7-1.3 3-3 3H7c-1.7 0-3-1.3-3-3V7c0-1.7 1.3-3 3-3zm11 1a1 1 0 1 0 0 2 1 1 0 0 0 0-2zM12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10zm0 2a3 3 0 1 1 0 6 3 3 0 0 1 0-6z"/></svg></span>@ashley.morgan</div>
    </div>
    <div class="zmon-so__c">
      {%- assign im = p.images[3] -%}
      {%- if im -%}<img src="{{ im | image_url: width: 600 }}" alt="" loading="lazy">{%- endif -%}
      <div class="zmon-so__tag"><span class="zmon-so__ig"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M7 2C4.2 2 2 4.2 2 7v10c0 2.8 2.2 5 5 5h10c2.8 0 5-2.2 5-5V7c0-2.8-2.2-5-5-5H7zm0 2h10c1.7 0 3 1.3 3 3v10c0 1.7-1.3 3-3 3H7c-1.7 0-3-1.3-3-3V7c0-1.7 1.3-3 3-3zm11 1a1 1 0 1 0 0 2 1 1 0 0 0 0-2zM12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10zm0 2a3 3 0 1 1 0 6 3 3 0 0 1 0-6z"/></svg></span>@elena.marr</div>
    </div>
  </div>
</div>
<style>
.zmon-so{
  --zmon-ink: rgb(var(--color-base-text));
  --zmon-accent: rgb(var(--color-base-accent-1));
  --zmon-accent-2: rgb(var(--color-base-accent-2));
  --zmon-on-accent: rgb(var(--color-base-solid-button-labels));
  --zmon-soft: rgb(var(--color-base-accent-1) / 0.10);
  --zmon-line: rgb(var(--color-base-accent-1) / 0.22);
  --zmon-muted: rgb(var(--color-base-text) / 0.62);
  /* couleurs SEMANTIQUES (alerte / disponibilite), hors palette de marque */
  --zmon-warn: #E68A00;
  --zmon-ok: #00B67A;
max-width:1200px;margin:0 auto;padding:45px 5px;text-align:center}
.zmon-so__t{font-family:var(--font-heading-family);font-size:29px;font-weight:400;line-height:1.15;
  letter-spacing:-.015em;margin:0 0 12px;color:var(--zmon-ink)}
.zmon-so__s{font-size:14px;color:var(--zmon-ink);margin:0 0 32px}
.zmon-so__grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.zmon-so__c{position:relative;border-radius:18px;overflow:hidden;aspect-ratio:1/1;background:var(--zmon-soft)}
.zmon-so__c img{width:100%;height:100%;object-fit:cover;display:block}
.zmon-so__tag{position:absolute;bottom:12px;left:12px;display:flex;align-items:center;gap:6px;
  color:#fff;font-size:14px;font-weight:500;text-shadow:0 1px 3px rgba(0,0,0,.45)}
.zmon-so__ig{width:16px;height:16px;display:block}
.zmon-so__ig svg{width:100%;height:100%;fill:#fff;display:block}
@media(min-width:769px){.zmon-so__t{font-size:44px}.zmon-so__grid{grid-template-columns:repeat(4,1fr)}}
</style>
